commands.command:
$gcValidationRoot = 'C:/Users/robso/AppData/Local/Temp/skills-wave2-validation-Bu1zNV/jvm-gc-tuning-validation'
New-Item -ItemType Directory -Path $gcValidationRoot -Force | Out-Null
$gcCases = @(
    @{ name='one-cpu-default'; flags=@('-XX:ActiveProcessorCount=1','-Xms16m','-Xmx512m'); expectedCollector='UseSerialGC'; parallel=$null; concurrent=$null },
    @{ name='g1-four-cpus'; flags=@('-XX:+UseG1GC','-XX:ActiveProcessorCount=4','-Xms16m','-Xmx512m'); expectedCollector='UseG1GC'; parallel=4; concurrent=1 },
    @{ name='g1-sixteen-cpus'; flags=@('-XX:+UseG1GC','-XX:ActiveProcessorCount=16','-Xms16m','-Xmx512m'); expectedCollector='UseG1GC'; parallel=13; concurrent=3 },
    @{ name='zgc-eight-cpus-512m'; flags=@('-XX:+UseZGC','-XX:ActiveProcessorCount=8','-Xms16m','-Xmx512m'); expectedCollector='UseZGC'; parallel=5; concurrent=2 },
    @{ name='zgc-two-cpus-512m'; flags=@('-XX:+UseZGC','-XX:ActiveProcessorCount=2','-Xms16m','-Xmx512m'); expectedCollector='UseZGC'; parallel=2; concurrent=1 },
    @{ name='zgc-eight-cpus-64m'; flags=@('-XX:+UseZGC','-XX:ActiveProcessorCount=8','-Xms16m','-Xmx64m'); expectedCollector='UseZGC'; parallel=1; concurrent=1 },
    @{ name='zgc-two-cpus-64m'; flags=@('-XX:+UseZGC','-XX:ActiveProcessorCount=2','-Xms16m','-Xmx64m'); expectedCollector='UseZGC'; parallel=1; concurrent=1 }
)
$gcResults = foreach ($gcCase in $gcCases) {
    $gcFlags = $gcCase.flags
    $gcOutput = & java @gcFlags '-XX:+PrintFlagsFinal' '-version' 2>&1
    $gcExit = $LASTEXITCODE
    $gcText = $gcOutput | Out-String
    $gcLog = Join-Path $gcValidationRoot ($gcCase.name + '.txt')
    $gcText | Set-Content -LiteralPath $gcLog
    if ($gcExit -ne 0) { throw ($gcCase.name + ' failed startup: ' + $gcText) }
    if ($gcText -notmatch ('(?m)^\s+bool\s+' + $gcCase.expectedCollector + '\s+=\s+true')) { throw ($gcCase.name + ' selected another collector') }
    $gcParallel = [int]([regex]::Match($gcText, '(?m)^\s+\w+\s+ParallelGCThreads\s+=\s+(\d+)').Groups[1].Value)
    $gcConcurrent = [int]([regex]::Match($gcText, '(?m)^\s+\w+\s+ConcGCThreads\s+=\s+(\d+)').Groups[1].Value)
    if (($null -ne $gcCase.parallel) -and ($gcParallel -ne $gcCase.parallel)) { throw ($gcCase.name + ' ParallelGCThreads mismatch') }
    if (($null -ne $gcCase.concurrent) -and ($gcConcurrent -ne $gcCase.concurrent)) { throw ($gcCase.name + ' ConcGCThreads mismatch') }
    [pscustomobject]@{ name=$gcCase.name; flags=$gcFlags; exitCode=$gcExit; collector=$gcCase.expectedCollector; parallel=$gcParallel; concurrent=$gcConcurrent; log=$gcLog }
}
$gcResults | ConvertTo-Json -Depth 5

@'
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { parseManifest } from './packages/core/src/domain/manifest.ts';
import { parseSkillDocument, documentName, documentDescription } from './packages/core/src/domain/skill-document.ts';
const root = path.resolve('skills/jvm-gc-tuning');
const files = ['SKILL.md', 'skill.yaml', 'references/collector-and-heap.md'];
const parsed = parseManifest(fs.readFileSync(path.join(root,'skill.yaml'),'utf8'), {strict:true});
assert.deepEqual(parsed.issues, []);
const main = fs.readFileSync(path.join(root,'SKILL.md'),'utf8');
const doc = parseSkillDocument(main);
assert.equal(documentName(doc), parsed.manifest.name);
assert.equal(documentDescription(doc), parsed.manifest.description);
assert.equal(parsed.manifest.version, '2.5.4');
for (const file of parsed.manifest.files) assert.ok(fs.existsSync(path.join(root,file)),file);
assert.ok(main.includes('references/collector-and-heap.md'));
let localLinks=0;
for (const file of files.filter(file=>file.endsWith('.md'))) {
  const text=fs.readFileSync(path.join(root,file),'utf8');
  for (const match of text.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)) {
    if (/^[a-z][a-z0-9+.-]*:/i.test(match[1])) continue;
    const target=path.resolve(root,path.dirname(file),match[1].split('#')[0]);
    assert.ok(target.startsWith(root+path.sep),match[1]);
    assert.ok(fs.existsSync(target),match[1]);
    localLinks++;
  }
}
console.log(JSON.stringify({version:parsed.manifest.version,strictManifestIssues:0,descriptionEqual:true,files:files.length,routedReferences:1,localLinks}));
'@ | node --input-type=module
